const $=id=>document.getElementById(id);
export const MODE_PATH={text:'/v1/chat/completions',image:'/v1/images/generations',voice:'/v1/audio/speech',video:'/v1/videos'};
export function compatibleModes(provider,paths){return Object.entries(MODE_PATH).filter(([mode,path])=>mode==='text'?paths.some(x=>['/v1/chat/completions','/v1/messages','/v1beta/models/MODEL:generateContent'].includes(x)):paths.includes(path)).map(([mode])=>mode)}
export function restrictOptions(select,allowed){for(const o of select.options){o.disabled=!allowed.includes(o.value);o.hidden=o.disabled}if(!allowed.includes(select.value))select.value=allowed[0]||''}
export function mediaParams(prefix){
 let extra=JSON.parse($(prefix==='chat'?'chat-media-options':'media-params').value||'{}');if(!extra||typeof extra!=='object'||Array.isArray(extra))throw Error('As opções avançadas devem ser um objeto JSON.');
 for(const key of ['size','quality','voice','response_format','seconds']){const value=$(prefix+'-media-'+key).value;if(value!==''){extra[key]=key==='seconds'?Number(value):value}}
 if(extra.seconds!=null&&(!Number.isFinite(extra.seconds)||extra.seconds<=0))throw Error('Duração inválida.');return extra;
}
export function mediaFields(prefix,mode,routes,provider,model){
 const path=MODE_PATH[mode];const choices=routes.filter(r=>r.provider===provider&&r.path===path&&r.approved&&(model==='biziva-auto'||r.model===model));
 for(const key of ['size','quality','voice','response_format','seconds']){const select=$(prefix+'-media-'+key);const prior=select.value;select.replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent='Padrão do modelo';select.append(empty);for(const v of new Set(choices.flatMap(r=>r.constraints?.[key]||[]))){const o=document.createElement('option');o.value=String(v);o.textContent=String(v);select.append(o)}if([...select.options].some(o=>o.value===prior))select.value=prior;select.closest('label').hidden=mode==='image'?!['size','quality','response_format'].includes(key):mode==='voice'?!['voice','response_format'].includes(key):!['size','seconds'].includes(key)}
}
export function chooseCurrency(id,routes,provider){const currencies=[...new Set(routes.filter(r=>r.provider===provider&&r.approved).map(r=>r.priceCurrency||'USD'))];if(currencies.length===1)$(id).value=currencies[0]}
let generation=0,urls=[];
export function clearControls(){generation++;for(const url of urls)URL.revokeObjectURL(url);urls=[];for(const id of ['recovery-code','backup-result','operation-detail','operations-list','biziva-check-result','security-result','recovery-result'])$(id).textContent='';for(const id of ['security-current','security-password','backup-password','backup-current','recover-code','recover-password'])$(id).value='';$('backup-file').value='';$('backup-download').hidden=true;$('biziva-models').replaceChildren();$('use-biziva-model').disabled=true;$('use-biziva-model').onclick=null}
export async function mountControls(api,notify,refresh,replaceToken){
 clearControls();const gen=generation;const guard=(id,fn)=>{$(id).onclick=async()=>{$(id).disabled=true;try{await fn()}catch(e){if(gen===generation)notify(e.message)}finally{$(id).disabled=false}}};
 const info=await api('/router/installation');if(gen!==generation)return;$('quit-app').hidden=!info.canQuit;
 guard('quit-app',async()=>{if(!$('quit-confirm').checked)throw Error('Marque a confirmação para encerrar o aplicativo.');await api('/router/quit','POST',{confirm:true});notify('Router encerrando. Pode fechar esta aba e abrir o aplicativo novamente quando quiser.')});
 guard('change-password',async()=>{const r=await api('/router/password','POST',{currentPassword:$('security-current').value,password:$('security-password').value});if(gen!==generation)return;replaceToken(r.token);$('security-current').value='';$('security-password').value='';notify(r.warning)});
 guard('generate-recovery',async()=>{const r=await api('/router/recovery-code','POST',{currentPassword:$('security-current').value});if(gen!==generation)return;$('security-current').value='';$('recovery-code').textContent=r.code+'\n'+r.warning});$('hide-recovery').onclick=()=>{$('recovery-code').textContent=''};
 guard('export-backup',async()=>{const r=await api('/router/backup','POST',{currentPassword:$('backup-current').value,password:$('backup-password').value});if(gen!==generation)return;const url=URL.createObjectURL(new Blob([JSON.stringify(r.backup)],{type:'application/json'}));urls.push(url);$('backup-download').href=url;$('backup-download').hidden=false;$('backup-current').value='';$('backup-password').value='';$('backup-result').textContent='Backup criptografado pronto. Guarde a senha separadamente; inclui chaves, conversas e proteção contra pedidos duplicados.'});
 guard('restore-backup',async()=>{if(!$('restore-confirm').checked)throw Error('Confirme a importação do backup.');const file=$('backup-file').files[0];if(!file||file.size>12500000)throw Error('Selecione um backup de até 12 MB.');const backup=JSON.parse(await file.text());const r=await api('/router/restore','POST',{currentPassword:$('backup-current').value,password:$('backup-password').value,backup,confirm:true});if(gen!==generation)return;$('backup-result').textContent=JSON.stringify(r);$('backup-current').value='';$('backup-password').value='';$('backup-file').value='';await refresh();notify('Importação concluída. Chaves e rotas já existentes foram preservadas. Entre novamente para recarregar as rotas.')});
 guard('check-biziva',async()=>{const r=await api('/router/biziva/check','POST',{});if(gen!==generation)return;const select=$('biziva-models');select.replaceChildren();for(const [i,m] of r.models.entries()){const o=document.createElement('option');o.value=i;o.textContent=`${m.name} · ${m.priceCurrency} ${m.inputUsdPerMillion}/1M entrada · ${m.outputUsdPerMillion}/1M saída`;select.append(o)}$('biziva-check-result').textContent=r.warning;$('use-biziva-model').disabled=!r.models.length;
 $('use-biziva-model').onclick=()=>{const m=r.models[Number(select.value)];if(!m)return;document.dispatchEvent(new Event('router-new-route'));document.querySelector('[data-view="routes"]').click();document.querySelector('#routes-panel details').open=true;for(const [id,value] of Object.entries({'route-provider':'biziva','route-path':m.path,'route-model':m.model,'input-price':m.inputUsdPerMillion,'output-price':m.outputUsdPerMillion,'route-context':m.contextTokens,'route-currency':m.priceCurrency}))$(id).value=value;$('route-provider').dispatchEvent(new Event('change'));$('approve-route').checked=false;notify('Preço e modelo da sua conta preenchidos, na moeda exibida. Escolha a tarefa e aprove a qualidade antes de salvar.')}});
 async function operations(){const r=await api('/router/operations');if(gen!==generation)return;$('operations-list').replaceChildren();for(const op of r.operations){const row=document.createElement('article'),label=document.createElement('p');label.textContent=`${op.idem} · ${op.state} · ${op.receipt?.provider||'provedor'} · ${new Date(op.created_at).toLocaleString()}`;row.append(label);for(const [text,suffix] of [['Ver resposta salva',''],['Consultar status no provedor','/status']]){if(suffix&&!(op.receipt?.provider==='openai'&&op.receipt?.resourceType))continue;const b=document.createElement('button');b.className='secondary';b.textContent=text;b.onclick=async()=>{b.disabled=true;try{const detail=await api('/router/operations/'+encodeURIComponent(op.idem)+suffix);if(gen===generation)$('operation-detail').textContent=JSON.stringify(detail,null,2)}catch(e){notify(e.message)}finally{b.disabled=false}};row.append(b)}$('operations-list').append(row)}}
 guard('refresh-operations',operations);
}
